import sys, json

class ListNode:
    def __init__(self, val=0, next=None):
        self.val=val
        self.next=next

    @staticmethod
    def from_list(values):
        if not values: return None
        head=ListNode(values[0]); cur=head
        for v in values[1:]:
            cur.next=ListNode(v); cur=cur.next
        return head

    def to_list(self):
        out=[]; cur=self
        while cur:
            out.append(cur.val); cur=cur.next
        return out

